// // // // // // // // // // // // // // // // // // //         }).filter(Boolean).join('');
// // // // // // // // // // // // // // // // // // //         tooltip.classed('visible', true).html(rows);
// // // // // // // // // // // // // // // // // // //         if (onNodeHover) onNodeHover(d);
// // // // // // // // // // // // // // // // // // //       })
// // // // // // // // // // // // // // // // // // //       .on('mousemove', (event) => {
// // // // // // // // // // // // // // // // // // //         const rect = container.getBoundingClientRect();
// // // // // // // // // // // // // // // // // // //         tooltip
