// // // // // // // // // // // // // // // // // // //       });

// // // // // // // // // // // // // // // // // // //     // Tooltip for edges (hit target catches events)
// // // // // // // // // // // // // // // // // // //     linkHit
// // // // // // // // // // // // // // // // // // //       .on('mouseover', (event, d) => {
// // // // // // // // // // // // // // // // // // //         const s = edgeStyle(d.type, data.edgeTypes);
// // // // // // // // // // // // // // // // // // //         const src = nodeById[typeof d.source === 'object' ? d.source.id : d.source];
// // // // // // // // // // // // // // // // // // //         const tgt = nodeById[typeof d.target === 'object' ? d.target.id : d.target];
// // // // // // // // // // // // // // // // // // //         const html = `
// // // // // // // // // // // // // // // // // // //           <div class="kg-tt-edge-ends">${src.label || src.id} &rarr; ${tgt.label || tgt.id}</div>
// // // // // // // // // // // // // // // // // // //           <div class="kg-tt-name">${src.label || src.id} ${s.phrase} ${tgt.label || tgt.id}</div>
// // // // // // // // // // // // // // // // // // //           <div class="kg-tt-type">${d.type}</div>`;
// // // // // // // // // // // // // // // // // // //         tooltip.classed('visible', true).html(html);
// // // // // // // // // // // // // // // // // // //       })
// // // // // // // // // // // // // // // // // // //       .on('mousemove', (event) => {
// // // // // // // // // // // // // // // // // // //         const rect = container.getBoundingClientRect();
// // // // // // // // // // // // // // // // // // //         tooltip
// // // // // // // // // // // // // // // // // // //           .style('left', (event.clientX - rect.left + 14) + 'px')
// // // // // // // // // // // // // // // // // // //           .style('top',  (event.clientY - rect.top - 24) + 'px');
