// // // // // // // // // // // // // // // // // // //     // Simulation
// // // // // // // // // // // // // // // // // // //     const simulation = d3
// // // // // // // // // // // // // // // // // // //       .forceSimulation(nodesCopy)
// // // // // // // // // // // // // // // // // // //       .force('link', d3.forceLink(edgesCopy).id((d) => d.id).distance(80).strength(0.35))
// // // // // // // // // // // // // // // // // // //       .force('charge', d3.forceManyBody().strength(-260))
// // // // // // // // // // // // // // // // // // //       .force('center', d3.forceCenter(width / 2, height / 2))
// // // // // // // // // // // // // // // // // // //       .force('collide', d3.forceCollide().radius((d) => nodeSize(degree[d.id]) + 4));

// // // // // // // // // // // // // // // // // // //     simulationRef.current = simulation;

// // // // // // // // // // // // // // // // // // //     // Tick: compute node positions, then draw edges as paths (straight for 1-edge pairs, arcs otherwise)
// // // // // // // // // // // // // // // // // // //     simulation.on('tick', () => {
// // // // // // // // // // // // // // // // // // //       linkPath.attr('d', edgePathFn);
// // // // // // // // // // // // // // // // // // //       linkHit.attr('d', edgePathFn);
// // // // // // // // // // // // // // // // // // //       node.attr('transform', (d) => `translate(${d.x},${d.y})`);
// // // // // // // // // // // // // // // // // // //     });

// // // // // // // // // // // // // // // // // // //     function edgePathFn(d) {
// // // // // // // // // // // // // // // // // // //       const src = typeof d.source === 'object' ? d.source : nodeById[d.source];
// // // // // // // // // // // // // // // // // // //       const tgt = typeof d.target === 'object' ? d.target : nodeById[d.target];
// // // // // // // // // // // // // // // // // // //       const x1 = src.x, y1 = src.y, x2 = tgt.x, y2 = tgt.y;
// // // // // // // // // // // // // // // // // // //       const dx = x2 - x1, dy = y2 - y1;
// // // // // // // // // // // // // // // // // // //       const dist = Math.sqrt(dx * dx + dy * dy) || 1;

// // // // // // // // // // // // // // // // // // //       // Trim endpoints so the arrowhead sits at the circle edge
// // // // // // // // // // // // // // // // // // //       const rs = nodeSize(degree[src.id]) + 2;
// // // // // // // // // // // // // // // // // // //       const rt = nodeSize(degree[tgt.id]) + 4;
// // // // // // // // // // // // // // // // // // //       const ux = dx / dist, uy = dy / dist;
// // // // // // // // // // // // // // // // // // //       const sx = x1 + ux * rs, sy = y1 + uy * rs;
// // // // // // // // // // // // // // // // // // //       const tx = x2 - ux * rt, ty = y2 - uy * rt;

// // // // // // // // // // // // // // // // // // //       if (d._pairSize <= 1) {
// // // // // // // // // // // // // // // // // // //         return `M ${sx} ${sy} L ${tx} ${ty}`;
// // // // // // // // // // // // // // // // // // //       }
// // // // // // // // // // // // // // // // // // //       // Arc
// // // // // // // // // // // // // // // // // // //       const off = ((d._pairIndex - (d._pairSize - 1) / 2) /
// // // // // // // // // // // // // // // // // // //                    Math.max(1, (d._pairSize - 1) / 2)) * 22;
// // // // // // // // // // // // // // // // // // //       const nx = -uy, ny = ux;
// // // // // // // // // // // // // // // // // // //       const midX = (sx + tx) / 2 + nx * off;
// // // // // // // // // // // // // // // // // // //       const midY = (sy + ty) / 2 + ny * off;
// // // // // // // // // // // // // // // // // // //       return `M ${sx} ${sy} Q ${midX} ${midY} ${tx} ${ty}`;
// // // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // // //     // Store handles for later effects
// // // // // // // // // // // // // // // // // // //     stateRef.current = {
// // // // // // // // // // // // // // // // // // //       linkPath, linkHit, node, edgesCopy, nodesCopy,
// // // // // // // // // // // // // // // // // // //       nodeById, degree, domainColorMap, edgeTypes: data.edgeTypes,
// // // // // // // // // // // // // // // // // // //       selectedId: null
// // // // // // // // // // // // // // // // // // //     };

// // // // // // // // // // // // // // // // // // //     return () => {
