// // // // // // // // // // // // // // // // // // //       return nodeVisible(s) && nodeVisible(t);
// // // // // // // // // // // // // // // // // // //     };

// // // // // // // // // // // // // // // // // // //     node.style('display', (d) => (nodeVisible(d) ? null : 'none'));
// // // // // // // // // // // // // // // // // // //     linkPath.style('display', (d) => (edgeVisible(d) ? null : 'none'));
// // // // // // // // // // // // // // // // // // //     linkHit.style('display', (d) => (edgeVisible(d) ? null : 'none'));
// // // // // // // // // // // // // // // // // // //   }, [activeFilters]);

