// // // // // // // // // // // // // // // // // // import { useEffect, useRef } from 'react';
// // // // // // // // // // // // // // // // // // import * as d3 from 'd3';

// // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // //  * Default edge style palette (used when data doesn't specify style per type).
// // // // // // // // // // // // // // // // // //  * Keys are edge type names; values follow the same shape as data.edgeTypes[type].
// // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // const DEFAULT_EDGE_STYLES = {
// // // // // // // // // // // // // // // // // //   'based-on':        { color: '#2563eb', width: 1.6, dash: null,  phrase: 'is based on' },
// // // // // // // // // // // // // // // // // //   'requires':        { color: '#60a5fa', width: 1.3, dash: '5,3', phrase: 'requires' },
// // // // // // // // // // // // // // // // // //   'specializes':     { color: '#ea580c', width: 1.6, dash: '5,3', phrase: 'specializes' },
// // // // // // // // // // // // // // // // // //   'proves':          { color: '#c2410c', width: 2.0, dash: null,  phrase: 'proves' },
// // // // // // // // // // // // // // // // // //   'precondition-of': { color: '#d97706', width: 1.4, dash: '2,2', phrase: 'is a precondition of' },
// // // // // // // // // // // // // // // // // //   'alternative-to':  { color: '#1e40af', width: 1.6, dash: '6,3', phrase: 'is an alternative to' },
// // // // // // // // // // // // // // // // // //   'inverse-of':      { color: '#1e3a8a', width: 2.0, dash: null,  phrase: 'is the inverse of' },
// // // // // // // // // // // // // // // // // //   'similar-to':      { color: '#9ca3af', width: 1.1, dash: null,  phrase: 'is similar to' },
// // // // // // // // // // // // // // // // // //   'contrasts-with':  { color: '#6b7280', width: 1.4, dash: '3,3', phrase: 'contrasts with' }
// // // // // // // // // // // // // // // // // // };

// // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // //  * Default domain color palette (used if no domainColors prop provided).
// // // // // // // // // // // // // // // // // //  * Assigned by insertion order.
// // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // const DEFAULT_DOMAIN_COLORS = [
// // // // // // // // // // // // // // // // // //   '#6b7280', '#bfdbfe', '#2563eb', '#1e40af',
// // // // // // // // // // // // // // // // // //   '#374151', '#1f2937', '#94a3b8', '#0f172a'
// // // // // // // // // // // // // // // // // // ];

// // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // //  * Compute the effective color/style for an edge type.
// // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // function edgeStyle(type, edgeTypes) {
// // // // // // // // // // // // // // // // // //   const fromData = edgeTypes?.[type] || {};
// // // // // // // // // // // // // // // // // //   const fromDefault = DEFAULT_EDGE_STYLES[type] || {};
// // // // // // // // // // // // // // // // // //   return {
// // // // // // // // // // // // // // // // // //     color: fromData.color || fromDefault.color || '#9ca3af',
// // // // // // // // // // // // // // // // // //     width: fromData.width ?? fromDefault.width ?? 1.4,
// // // // // // // // // // // // // // // // // //     dash:  fromData.dash  ?? fromDefault.dash  ?? null,
// // // // // // // // // // // // // // // // // //     phrase: fromData.phrase || fromDefault.phrase || type.replace(/-/g, ' '),
// // // // // // // // // // // // // // // // // //     symmetric: fromData.symmetric ?? false
// // // // // // // // // // // // // // // // // //   };
// // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // //  * Assign colors to a list of domain values.
// // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // function buildDomainColorMap(nodes, override) {
// // // // // // // // // // // // // // // // // //   if (override) return override;
// // // // // // // // // // // // // // // // // //   const domains = Array.from(new Set(nodes.map((n) => n.domain).filter(Boolean)));
// // // // // // // // // // // // // // // // // //   const map = {};
// // // // // // // // // // // // // // // // // //   domains.forEach((d, i) => {
// // // // // // // // // // // // // // // // // //     map[d] = DEFAULT_DOMAIN_COLORS[i % DEFAULT_DOMAIN_COLORS.length];
// // // // // // // // // // // // // // // // // //   });
// // // // // // // // // // // // // // // // // //   return map;
// // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // //  * Group edges by unordered node pair. Returns a Map from "a||b" to array of edges.
// // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // function groupEdgesByPair(edges) {
// // // // // // // // // // // // // // // // // //   const pairs = new Map();
// // // // // // // // // // // // // // // // // //   edges.forEach((e, idx) => {
// // // // // // // // // // // // // // // // // //     const s = typeof e.source === 'object' ? e.source.id : e.source;
// // // // // // // // // // // // // // // // // //     const t = typeof e.target === 'object' ? e.target.id : e.target;
// // // // // // // // // // // // // // // // // //     const key = [s, t].sort().join('||');
// // // // // // // // // // // // // // // // // //     if (!pairs.has(key)) pairs.set(key, []);
// // // // // // // // // // // // // // // // // //     pairs.get(key).push({ ...e, _idx: idx });
// // // // // // // // // // // // // // // // // //   });
// // // // // // // // // // // // // // // // // //   return pairs;
// // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // //  * KnowledgeGraph — force-directed graph view.
// // // // // // // // // // // // // // // // // //  *
// // // // // // // // // // // // // // // // // //  * Props:
// // // // // // // // // // // // // // // // // //  *   data              — { nodes, edges, edgeTypes }
// // // // // // // // // // // // // // // // // //  *   activeFilters     — { domains: Set, types: Set, edgeTypes: Set }
// // // // // // // // // // // // // // // // // //  *   selectedNode      — id of selected node, or null
// // // // // // // // // // // // // // // // // //  *   onNodeSelect      — (nodeId) => void; call with null to deselect
// // // // // // // // // // // // // // // // // //  *   onBackgroundClick — () => void
// // // // // // // // // // // // // // // // // //  *   onHover           — (info | null) => void; info is:
// // // // // // // // // // // // // // // // // //  *                          { kind: "node", node }        when a node is hovered
// // // // // // // // // // // // // // // // // //  *                          { kind: "edge", edge, source, target, phrase } when an edge is hovered
// // // // // // // // // // // // // // // // // //  *                          null                          on mouseout
// // // // // // // // // // // // // // // // // //  *   domainColors      — optional { [domain]: color } override
// // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // export default function KnowledgeGraph({
// // // // // // // // // // // // // // // // // //   data,
// // // // // // // // // // // // // // // // // //   activeFilters,
// // // // // // // // // // // // // // // // // //   selectedNode,
// // // // // // // // // // // // // // // // // //   onNodeSelect,
// // // // // // // // // // // // // // // // // //   onBackgroundClick,
// // // // // // // // // // // // // // // // // //   onHover,
// // // // // // // // // // // // // // // // // //   domainColors: domainColorsProp
// // // // // // // // // // // // // // // // // // }) {
// // // // // // // // // // // // // // // // // //   const containerRef = useRef(null);
// // // // // // // // // // // // // // // // // //   const svgRef = useRef(null);
// // // // // // // // // // // // // // // // // //   const simulationRef = useRef(null);
// // // // // // // // // // // // // // // // // //   const stateRef = useRef({}); // holds selections and derived structures

// // // // // // // // // // // // // // // // // //   // ---------- Initial build (data change → full rebuild) ----------
// // // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // // //     if (!data) return;
// // // // // // // // // // // // // // // // // //     const container = containerRef.current;
// // // // // // // // // // // // // // // // // //     if (!container) return;

// // // // // // // // // // // // // // // // // //     // Clear any previous
// // // // // // // // // // // // // // // // // //     d3.select(container).selectAll('svg').remove();

// // // // // // // // // // // // // // // // // //     const width = container.clientWidth || 800;
// // // // // // // // // // // // // // // // // //     const height = container.clientHeight || 600;

// // // // // // // // // // // // // // // // // //     const domainColorMap = buildDomainColorMap(data.nodes, domainColorsProp);

// // // // // // // // // // // // // // // // // //     // Compute degree
// // // // // // // // // // // // // // // // // //     const degree = {};
// // // // // // // // // // // // // // // // // //     data.nodes.forEach((n) => { degree[n.id] = 0; });
// // // // // // // // // // // // // // // // // //     data.edges.forEach((e) => {
// // // // // // // // // // // // // // // // // //       degree[typeof e.source === 'object' ? e.source.id : e.source] =
// // // // // // // // // // // // // // // // // //         (degree[typeof e.source === 'object' ? e.source.id : e.source] || 0) + 1;
// // // // // // // // // // // // // // // // // //       degree[typeof e.target === 'object' ? e.target.id : e.target] =
// // // // // // // // // // // // // // // // // //         (degree[typeof e.target === 'object' ? e.target.id : e.target] || 0) + 1;
// // // // // // // // // // // // // // // // // //     });

// // // // // // // // // // // // // // // // // //     const maxDeg = Math.max(1, ...Object.values(degree));
// // // // // // // // // // // // // // // // // //     const nodeSize = d3.scaleSqrt().domain([0, maxDeg]).range([5, 22]);

// // // // // // // // // // // // // // // // // //     // Deep-copy edges/nodes for simulation
// // // // // // // // // // // // // // // // // //     const nodesCopy = data.nodes.map((n) => ({ ...n }));
// // // // // // // // // // // // // // // // // //     const edgesCopy = data.edges.map((e) => ({ ...e }));

// // // // // // // // // // // // // // // // // //     const nodeById = {};
// // // // // // // // // // // // // // // // // //     nodesCopy.forEach((n) => { nodeById[n.id] = n; });

// // // // // // // // // // // // // // // // // //     const svg = d3
// // // // // // // // // // // // // // // // // //       .select(container)
// // // // // // // // // // // // // // // // // //       .append('svg')
// // // // // // // // // // // // // // // // // //       .attr('class', 'kg-svg')
// // // // // // // // // // // // // // // // // //       .attr('viewBox', [0, 0, width, height])
// // // // // // // // // // // // // // // // // //       .attr('preserveAspectRatio', 'xMidYMid meet');
// // // // // // // // // // // // // // // // // //     svgRef.current = svg.node();

// // // // // // // // // // // // // // // // // //     // Transparent background rect for click-to-deselect
// // // // // // // // // // // // // // // // // //     svg
// // // // // // // // // // // // // // // // // //       .append('rect')
// // // // // // // // // // // // // // // // // //       .attr('class', 'kg-bg')
// // // // // // // // // // // // // // // // // //       .attr('x', 0).attr('y', 0)
// // // // // // // // // // // // // // // // // //       .attr('width', width).attr('height', height)
// // // // // // // // // // // // // // // // // //       .attr('fill', 'transparent')
// // // // // // // // // // // // // // // // // //       .on('click', () => onBackgroundClick && onBackgroundClick());

// // // // // // // // // // // // // // // // // //     // Arrow markers (per edge type + direction)
// // // // // // // // // // // // // // // // // //     const usedTypes = Array.from(new Set(edgesCopy.map((e) => e.type)));
// // // // // // // // // // // // // // // // // //     const defs = svg.append('defs');
// // // // // // // // // // // // // // // // // //     usedTypes.forEach((t) => {
// // // // // // // // // // // // // // // // // //       const s = edgeStyle(t, data.edgeTypes);
// // // // // // // // // // // // // // // // // //       ['end', 'start'].forEach((pos) => {
// // // // // // // // // // // // // // // // // //         defs
// // // // // // // // // // // // // // // // // //           .append('marker')
// // // // // // // // // // // // // // // // // //           .attr('id', `kg-arr-${t}-${pos}`)
// // // // // // // // // // // // // // // // // //           .attr('viewBox', '0 -4 8 8')
// // // // // // // // // // // // // // // // // //           .attr('refX', pos === 'end' ? 8 : 0)
// // // // // // // // // // // // // // // // // //           .attr('refY', 0)
// // // // // // // // // // // // // // // // // //           .attr('markerWidth', 6)
// // // // // // // // // // // // // // // // // //           .attr('markerHeight', 6)
// // // // // // // // // // // // // // // // // //           .attr('orient', pos === 'end' ? 'auto' : 'auto-start-reverse')
// // // // // // // // // // // // // // // // // //           .attr('markerUnits', 'userSpaceOnUse')
// // // // // // // // // // // // // // // // // //           .append('path')
// // // // // // // // // // // // // // // // // //           .attr('d', 'M0,-4L8,0L0,4')
// // // // // // // // // // // // // // // // // //           .attr('fill', s.color);
// // // // // // // // // // // // // // // // // //       });
// // // // // // // // // // // // // // // // // //     });

// // // // // // // // // // // // // // // // // //     // Zoom
// // // // // // // // // // // // // // // // // //     const zoomG = svg.append('g').attr('class', 'kg-zoom');
// // // // // // // // // // // // // // // // // //     const zoom = d3.zoom().scaleExtent([0.25, 4]).on('zoom', (event) => {
// // // // // // // // // // // // // // // // // //       zoomG.attr('transform', event.transform);
// // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // //     svg.call(zoom);

// // // // // // // // // // // // // // // // // //     // Group edges by pair for arc rendering
// // // // // // // // // // // // // // // // // //     const edgePairs = groupEdgesByPair(edgesCopy);
// // // // // // // // // // // // // // // // // //     // Assign each edge an arc offset index within its pair
// // // // // // // // // // // // // // // // // //     edgesCopy.forEach((e) => {
// // // // // // // // // // // // // // // // // //       const s = typeof e.source === 'object' ? e.source.id : e.source;
// // // // // // // // // // // // // // // // // //       const t = typeof e.target === 'object' ? e.target.id : e.target;
// // // // // // // // // // // // // // // // // //       const key = [s, t].sort().join('||');
// // // // // // // // // // // // // // // // // //       const group = edgePairs.get(key);
// // // // // // // // // // // // // // // // // //       e._pairSize = group.length;
// // // // // // // // // // // // // // // // // //       e._pairIndex = group.findIndex((g) => g._idx === edgesCopy.indexOf(e));
// // // // // // // // // // // // // // // // // //     });

// // // // // // // // // // // // // // // // // //     // Links group
// // // // // // // // // // // // // // // // // //     const linkG = zoomG.append('g').attr('class', 'kg-links');

// // // // // // // // // // // // // // // // // //     // Visible paths
// // // // // // // // // // // // // // // // // //     const linkPath = linkG
// // // // // // // // // // // // // // // // // //       .selectAll('path.kg-link')
// // // // // // // // // // // // // // // // // //       .data(edgesCopy)
// // // // // // // // // // // // // // // // // //       .enter()
// // // // // // // // // // // // // // // // // //       .append('path')
// // // // // // // // // // // // // // // // // //       .attr('class', 'kg-link')
// // // // // // // // // // // // // // // // // //       .attr('fill', 'none')
// // // // // // // // // // // // // // // // // //       .attr('stroke', (d) => edgeStyle(d.type, data.edgeTypes).color)
// // // // // // // // // // // // // // // // // //       .attr('stroke-width', (d) => edgeStyle(d.type, data.edgeTypes).width)
// // // // // // // // // // // // // // // // // //       .attr('stroke-dasharray', (d) => edgeStyle(d.type, data.edgeTypes).dash)
// // // // // // // // // // // // // // // // // //       .attr('marker-end', (d) => `url(#kg-arr-${d.type}-end)`)
// // // // // // // // // // // // // // // // // //       .attr('marker-start', (d) => {
// // // // // // // // // // // // // // // // // //         const s = edgeStyle(d.type, data.edgeTypes);
// // // // // // // // // // // // // // // // // //         return s.symmetric ? `url(#kg-arr-${d.type}-start)` : null;
// // // // // // // // // // // // // // // // // //       });

// // // // // // // // // // // // // // // // // //     // Transparent thicker hit path (for hover)
// // // // // // // // // // // // // // // // // //     const linkHit = linkG
// // // // // // // // // // // // // // // // // //       .selectAll('path.kg-link-hit')
// // // // // // // // // // // // // // // // // //       .data(edgesCopy)
// // // // // // // // // // // // // // // // // //       .enter()
// // // // // // // // // // // // // // // // // //       .append('path')
// // // // // // // // // // // // // // // // // //       .attr('class', 'kg-link-hit')
// // // // // // // // // // // // // // // // // //       .attr('fill', 'none')
// // // // // // // // // // // // // // // // // //       .attr('stroke', 'transparent')
// // // // // // // // // // // // // // // // // //       .attr('stroke-width', 14)
// // // // // // // // // // // // // // // // // //       .attr('pointer-events', 'stroke')
// // // // // // // // // // // // // // // // // //       .style('cursor', 'pointer');

// // // // // // // // // // // // // // // // // //     // Node groups
// // // // // // // // // // // // // // // // // //     const nodeG = zoomG.append('g').attr('class', 'kg-nodes');
// // // // // // // // // // // // // // // // // //     const node = nodeG
// // // // // // // // // // // // // // // // // //       .selectAll('g.kg-node')
// // // // // // // // // // // // // // // // // //       .data(nodesCopy)
// // // // // // // // // // // // // // // // // //       .enter()
// // // // // // // // // // // // // // // // // //       .append('g')
// // // // // // // // // // // // // // // // // //       .attr('class', 'kg-node')
// // // // // // // // // // // // // // // // // //       .style('cursor', 'pointer');

// // // // // // // // // // // // // // // // // //     node
// // // // // // // // // // // // // // // // // //       .append('circle')
// // // // // // // // // // // // // // // // // //       .attr('r', (d) => nodeSize(degree[d.id]))
// // // // // // // // // // // // // // // // // //       .attr('fill', (d) => domainColorMap[d.domain] || '#94a3b8')
// // // // // // // // // // // // // // // // // //       .attr('stroke', (d) => {
// // // // // // // // // // // // // // // // // //         const c = d3.color(domainColorMap[d.domain] || '#94a3b8');
// // // // // // // // // // // // // // // // // //         return c ? c.darker(0.7).toString() : '#374151';
// // // // // // // // // // // // // // // // // //       })
// // // // // // // // // // // // // // // // // //       .attr('stroke-width', 1.2);

// // // // // // // // // // // // // // // // // //     node
// // // // // // // // // // // // // // // // // //       .append('text')
// // // // // // // // // // // // // // // // // //       .attr('class', 'kg-node-label')
// // // // // // // // // // // // // // // // // //       .attr('dx', (d) => nodeSize(degree[d.id]) + 4)
// // // // // // // // // // // // // // // // // //       .attr('dy', 3)
// // // // // // // // // // // // // // // // // //       .text((d) => d.label || d.id);

// // // // // // // // // // // // // // // // // //     // Drag
// // // // // // // // // // // // // // // // // //     const drag = d3.drag()
// // // // // // // // // // // // // // // // // //       .on('start', (event, d) => {
// // // // // // // // // // // // // // // // // //         if (!event.active) simulationRef.current.alphaTarget(0.3).restart();
// // // // // // // // // // // // // // // // // //         d.fx = d.x; d.fy = d.y;
// // // // // // // // // // // // // // // // // //       })
// // // // // // // // // // // // // // // // // //       .on('drag', (event, d) => {
// // // // // // // // // // // // // // // // // //         d.fx = event.x; d.fy = event.y;
// // // // // // // // // // // // // // // // // //       })
// // // // // // // // // // // // // // // // // //       .on('end', (event, d) => {
// // // // // // // // // // // // // // // // // //         if (!event.active) simulationRef.current.alphaTarget(0);
// // // // // // // // // // // // // // // // // //         // Pin on drop
// // // // // // // // // // // // // // // // // //       });
// // // // // // // // // // // // // // // // // //     node.call(drag);

// // // // // // // // // // // // // // // // // //     // Node click (with stopPropagation so it doesn't trigger background)
// // // // // // // // // // // // // // // // // //     node.on('click', (event, d) => {
// // // // // // // // // // // // // // // // // //       event.stopPropagation();
// // // // // // // // // // // // // // // // // //       if (onNodeSelect) {
// // // // // // // // // // // // // // // // // //         // Toggle: if already selected, deselect
// // // // // // // // // // // // // // // // // //         if (stateRef.current.selectedId === d.id) {
// // // // // // // // // // // // // // // // // //           onNodeSelect(null);
// // // // // // // // // // // // // // // // // //         } else {
// // // // // // // // // // // // // // // // // //           onNodeSelect(d.id);
// // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // //       }
// // // // // // // // // // // // // // // // // //     });

// // // // // // // // // // // // // // // // // //     // Double-click to unpin
// // // // // // // // // // // // // // // // // //     node.on('dblclick', (event, d) => {
// // // // // // // // // // // // // // // // // //       event.stopPropagation();
// // // // // // // // // // // // // // // // // //       d.fx = null; d.fy = null;
// // // // // // // // // // // // // // // // // //       simulationRef.current.alphaTarget(0.15).restart();
// // // // // // // // // // // // // // // // // //       setTimeout(() => simulationRef.current.alphaTarget(0), 300);
// // // // // // // // // // // // // // // // // //     });

// // // // // // // // // // // // // // // // // //     // Node hover → fire onHover callback (parent renders the strip)
// // // // // // // // // // // // // // // // // //     node
// // // // // // // // // // // // // // // // // //       .on('mouseover', (event, d) => {
