// // // // // // // // // // // // // // // // // //         if (onHover) onHover(null);
// // // // // // // // // // // // // // // // // //       });

// // // // // // // // // // // // // // // // // //     // Edge hover → fire onHover callback with source/target/phrase resolved
// // // // // // // // // // // // // // // // // //     linkHit
// // // // // // // // // // // // // // // // // //       .on('mouseover', (event, d) => {
// // // // // // // // // // // // // // // // // //         const src = nodeById[typeof d.source === 'object' ? d.source.id : d.source];
// // // // // // // // // // // // // // // // // //         const tgt = nodeById[typeof d.target === 'object' ? d.target.id : d.target];
// // // // // // // // // // // // // // // // // //         const s = edgeStyle(d.type, data.edgeTypes);
// // // // // // // // // // // // // // // // // //         if (onHover) onHover({
// // // // // // // // // // // // // // // // // //           kind: 'edge',
// // // // // // // // // // // // // // // // // //           edge: d,
// // // // // // // // // // // // // // // // // //           source: src,
// // // // // // // // // // // // // // // // // //           target: tgt,
// // // // // // // // // // // // // // // // // //           phrase: s.phrase
// // // // // // // // // // // // // // // // // //         });
// // // // // // // // // // // // // // // // // //       })
// // // // // // // // // // // // // // // // // //       .on('mouseout', () => {
// // // // // // // // // // // // // // // // // //         if (onHover) onHover(null);
// // // // // // // // // // // // // // // // // //       });

// // // // // // // // // // // // // // // // // //     // Simulation
// // // // // // // // // // // // // // // // // //     const simulation = d3
// // // // // // // // // // // // // // // // // //       .forceSimulation(nodesCopy)
