// // // // // // // // // // // // // // // // // //       linkPath, linkHit, node, edgesCopy, nodesCopy,
// // // // // // // // // // // // // // // // // //       nodeById, degree, domainColorMap, edgeTypes: data.edgeTypes,
// // // // // // // // // // // // // // // // // //       selectedId: null
// // // // // // // // // // // // // // // // // //     };

// // // // // // // // // // // // // // // // // //     return () => {
