// // // // // // // // // // // // // // // // // //       .attr('stroke', (d) => d.id === selectedNode
// // // // // // // // // // // // // // // // // //         ? '#dc2626'
// // // // // // // // // // // // // // // // // //         : d3.color(st.domainColorMap[d.domain] || '#94a3b8').darker(0.7).toString())
// // // // // // // // // // // // // // // // // //       .attr('stroke-width', (d) => d.id === selectedNode ? 2.5 : 1.2);
// // // // // // // // // // // // // // // // // //     linkPath
// // // // // // // // // // // // // // // // // //       .classed('kg-dimmed', (d, i) => !highlighted.has(i))
// // // // // // // // // // // // // // // // // //       .classed('kg-highlighted', (d, i) => highlighted.has(i));
// // // // // // // // // // // // // // // // // //   }, [selectedNode]);

// // // // // // // // // // // // // // // // // //   return (
// // // // // // // // // // // // // // // // // //     <div ref={containerRef} className="kg-container">
// // // // // // // // // // // // // // // // // //       <style>{`
// // // // // // // // // // // // // // // // // //         .kg-container {
