// // // // // // // // // // // // // // // // // const DEFAULT_EDGE_STYLES = {
// // // // // // // // // // // // // // // // //   'based-on':        { color: '#2563eb', width: 1.6, dash: null,  phrase: 'is based on' },
// // // // // // // // // // // // // // // // //   'requires':        { color: '#60a5fa', width: 1.3, dash: '5,3', phrase: 'requires' },
// // // // // // // // // // // // // // // // //   'specializes':     { color: '#ea580c', width: 1.6, dash: '5,3', phrase: 'specializes' },
