// // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // //  * KnowledgeGraph in clustered mode.
// // // // // // // // // // // // // // // // //  * Overview: domain bubbles arranged in a ring.
// // // // // // // // // // // // // // // // //  * Focus: click a bubble → its nodes expand with edges; other domains shrink to chips.
// // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // export default function KnowledgeGraph({
// // // // // // // // // // // // // // // // //   data,
// // // // // // // // // // // // // // // // //   activeFilters,
// // // // // // // // // // // // // // // // //   selectedNode,
// // // // // // // // // // // // // // // // //   onNodeSelect,
// // // // // // // // // // // // // // // // //   onBackgroundClick,
// // // // // // // // // // // // // // // // //   onHover,
// // // // // // // // // // // // // // // // //   focusedDomain,
// // // // // // // // // // // // // // // // //   onDomainFocus,
// // // // // // // // // // // // // // // // //   domainColors: domainColorsProp
// // // // // // // // // // // // // // // // // }) {
// // // // // // // // // // // // // // // // //   const containerRef = useRef(null);
// // // // // // // // // // // // // // // // //   const simulationRef = useRef(null);
// // // // // // // // // // // // // // // // //   const stateRef = useRef({});

// // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // //     if (!data) return;
// // // // // // // // // // // // // // // // //     const container = containerRef.current;
// // // // // // // // // // // // // // // // //     if (!container) return;

// // // // // // // // // // // // // // // // //     d3.select(container).selectAll('svg').remove();
// // // // // // // // // // // // // // // // //     container.querySelectorAll('.kg-back-btn').forEach((b) => b.remove());

// // // // // // // // // // // // // // // // //     const width = container.clientWidth || 800;
// // // // // // // // // // // // // // // // //     const height = container.clientHeight || 600;
// // // // // // // // // // // // // // // // //     const domainColorMap = buildDomainColorMap(data.nodes, domainColorsProp);
// // // // // // // // // // // // // // // // //     stateRef.current = { focusedDomain, domainColorMap };

// // // // // // // // // // // // // // // // //     if (focusedDomain) {
// // // // // // // // // // // // // // // // //       buildFocused(container, width, height, domainColorMap);
// // // // // // // // // // // // // // // // //     } else {
// // // // // // // // // // // // // // // // //       buildOverview(container, width, height, domainColorMap);
// // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // //     return () => {
