// // // // // // // // // // // // // // // // //       d3.select(container).selectAll('svg').remove();
// // // // // // // // // // // // // // // // //       container.querySelectorAll('.kg-back-btn').forEach((b) => b.remove());
// // // // // // // // // // // // // // // // //     };
// // // // // // // // // // // // // // // // //   }, [data, focusedDomain, domainColorsProp]);

// // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // //     if (!focusedDomain) return;
// // // // // // // // // // // // // // // // //     const st = stateRef.current;
