// // // // // // // // // ---------- Shape geometry helpers ----------
// // // // // // // // // Each returns the point where the ray from (cx, cy) toward (tx, ty)
// // // // // // // // // exits the shape's border. Used for arrow docking.

// // // // // // // // function rectIntersect(cx, cy, w, h, tx, ty) {
// // // // // // // //   const dx = tx - cx, dy = ty - cy;
// // // // // // // //   if (dx === 0 && dy === 0) return { x: cx, y: cy };
// // // // // // // //   const hw = w / 2, hh = h / 2;
// // // // // // // //   const scaleX = dx === 0 ? Infinity : hw / Math.abs(dx);
// // // // // // // //   const scaleY = dy === 0 ? Infinity : hh / Math.abs(dy);
// // // // // // // //   const scale = Math.min(scaleX, scaleY);
// // // // // // // //   return { x: cx + dx * scale, y: cy + dy * scale };
// // // // // // // // }

// // // // // // // // function ellipseIntersect(cx, cy, rx, ry, tx, ty) {
// // // // // // // //   const dx = tx - cx, dy = ty - cy;
// // // // // // // //   if (dx === 0 && dy === 0) return { x: cx, y: cy };
// // // // // // // //   const scale = 1 / Math.sqrt((dx * dx) / (rx * rx) + (dy * dy) / (ry * ry));
// // // // // // // //   return { x: cx + dx * scale, y: cy + dy * scale };
// // // // // // // // }

// // // // // // // // function circleIntersect(cx, cy, r, tx, ty) {
// // // // // // // //   const dx = tx - cx, dy = ty - cy;
// // // // // // // //   const len = Math.sqrt(dx * dx + dy * dy) || 1;
// // // // // // // //   return { x: cx + dx * r / len, y: cy + dy * r / len };
// // // // // // // // }

// // // // // // // // // Diamond border: |x/hw| + |y/hh| = 1
// // // // // // // // function diamondIntersect(cx, cy, hw, hh, tx, ty) {
// // // // // // // //   const dx = tx - cx, dy = ty - cy;
// // // // // // // //   if (dx === 0 && dy === 0) return { x: cx, y: cy };
// // // // // // // //   const scale = 1 / (Math.abs(dx) / hw + Math.abs(dy) / hh);
// // // // // // // //   return { x: cx + dx * scale, y: cy + dy * scale };
// // // // // // // // }

// // // // // // // // // Horizontal hexagon (flat top/bottom, points on left/right)
// // // // // // // // // inscribed in a w × h box, with 1/4-width indent from each vertical edge.
// // // // // // // // function hexPoints(w, h) {
// // // // // // // //   const qw = w / 4;
// // // // // // // //   const hh = h / 2;
// // // // // // // //   return [
// // // // // // // //     [-w / 2 + qw, -hh],
// // // // // // // //     [ w / 2 - qw, -hh],
// // // // // // // //     [ w / 2, 0],
// // // // // // // //     [ w / 2 - qw,  hh],
// // // // // // // //     [-w / 2 + qw,  hh],
// // // // // // // //     [-w / 2, 0]
// // // // // // // //   ].map((p) => p.join(',')).join(' ');
// // // // // // // // }

// // // // // // // // // ---------- Shape registry ----------
// // // // // // // // // Each entry defines:
// // // // // // // // //   tag      — SVG element to append
// // // // // // // // //   dim      — sizing function (label → { w, h, [r] })
// // // // // // // // //   apply    — bind geometry attributes to the data selection
// // // // // // // // //   intersect — border intersection point (pad inflates the border)
// // // // // // // // //   collide  — radius for d3.forceCollide
// // // // // // // // const SHAPES = {
// // // // // // // //   rect: {
// // // // // // // //     tag: 'rect',
// // // // // // // //     dim: (label) => ({ w: Math.max(64, label.length * 5.6 + 20), h: 24 }),
// // // // // // // //     apply: (sel, nodeDim) => sel
// // // // // // // //       .attr('x', (d) => -nodeDim.get(d.id).w / 2)
// // // // // // // //       .attr('y', (d) => -nodeDim.get(d.id).h / 2)
// // // // // // // //       .attr('width',  (d) => nodeDim.get(d.id).w)
// // // // // // // //       .attr('height', (d) => nodeDim.get(d.id).h)
// // // // // // // //       .attr('rx', 12),
// // // // // // // //     intersect: (cx, cy, dim, tx, ty, pad = 0) =>
// // // // // // // //       rectIntersect(cx, cy, dim.w + pad, dim.h + pad, tx, ty),
// // // // // // // //     collide: (dim) => Math.max(dim.w, dim.h) / 2 + 8
// // // // // // // //   },
// // // // // // // //   rectangle: {
// // // // // // // //     tag: 'rect',
// // // // // // // //     dim: (label) => ({ w: Math.max(64, label.length * 5.6 + 20), h: 24 }),
// // // // // // // //     apply: (sel, nodeDim) => sel
// // // // // // // //       .attr('x', (d) => -nodeDim.get(d.id).w / 2)
// // // // // // // //       .attr('y', (d) => -nodeDim.get(d.id).h / 2)
// // // // // // // //       .attr('width',  (d) => nodeDim.get(d.id).w)
// // // // // // // //       .attr('height', (d) => nodeDim.get(d.id).h)
// // // // // // // //       .attr('rx', 0),
// // // // // // // //     intersect: (cx, cy, dim, tx, ty, pad = 0) =>
// // // // // // // //       rectIntersect(cx, cy, dim.w + pad, dim.h + pad, tx, ty),
// // // // // // // //     collide: (dim) => Math.max(dim.w, dim.h) / 2 + 8
// // // // // // // //   },
// // // // // // // //   ellipse: {
// // // // // // // //     tag: 'ellipse',
// // // // // // // //     // Ellipses cut into their sides — need extra horizontal room to contain the same text.
// // // // // // // //     dim: (label) => ({ w: Math.max(80, label.length * 6.4 + 30), h: 28 }),
// // // // // // // //     apply: (sel, nodeDim) => sel
// // // // // // // //       .attr('rx', (d) => nodeDim.get(d.id).w / 2)
// // // // // // // //       .attr('ry', (d) => nodeDim.get(d.id).h / 2),
// // // // // // // //     intersect: (cx, cy, dim, tx, ty, pad = 0) =>
// // // // // // // //       ellipseIntersect(cx, cy, (dim.w + pad) / 2, (dim.h + pad) / 2, tx, ty),
// // // // // // // //     collide: (dim) => Math.max(dim.w, dim.h) / 2 + 8
// // // // // // // //   },
// // // // // // // //   circle: {
// // // // // // // //     tag: 'circle',
// // // // // // // //     // Radius sized so the label fits horizontally. Long labels blow this up — that's the point.
// // // // // // // //     dim: (label) => {
// // // // // // // //       const r = Math.max(22, label.length * 3.0 + 10);
// // // // // // // //       return { w: r * 2, h: r * 2, r };
// // // // // // // //     },
// // // // // // // //     apply: (sel, nodeDim) => sel.attr('r', (d) => nodeDim.get(d.id).r),
// // // // // // // //     intersect: (cx, cy, dim, tx, ty, pad = 0) =>
// // // // // // // //       circleIntersect(cx, cy, dim.r + pad / 2, tx, ty),
// // // // // // // //     collide: (dim) => dim.r + 8
// // // // // // // //   },
// // // // // // // //   hexagon: {
// // // // // // // //     tag: 'polygon',
// // // // // // // //     dim: (label) => ({ w: Math.max(72, label.length * 5.6 + 30), h: 28 }),
// // // // // // // //     apply: (sel, nodeDim) => sel.attr('points', (d) => {
// // // // // // // //       const { w, h } = nodeDim.get(d.id);
// // // // // // // //       return hexPoints(w, h);
// // // // // // // //     }),
// // // // // // // //     // Approximate a horizontal hexagon with a slightly narrower rect for docking.
// // // // // // // //     intersect: (cx, cy, dim, tx, ty, pad = 0) =>
// // // // // // // //       rectIntersect(cx, cy, (dim.w + pad) * 0.9, dim.h + pad, tx, ty),
// // // // // // // //     collide: (dim) => Math.max(dim.w, dim.h) / 2 + 8
// // // // // // // //   },
// // // // // // // //   diamond: {
// // // // // // // //     tag: 'polygon',
// // // // // // // //     // Diamonds are the worst for text — extra padding both ways.
// // // // // // // //     dim: (label) => ({ w: Math.max(90, label.length * 6.4 + 40), h: 42 }),
// // // // // // // //     apply: (sel, nodeDim) => sel.attr('points', (d) => {
// // // // // // // //       const { w, h } = nodeDim.get(d.id);
// // // // // // // //       return `0,${-h / 2} ${w / 2},0 0,${h / 2} ${-w / 2},0`;
// // // // // // // //     }),
// // // // // // // //     intersect: (cx, cy, dim, tx, ty, pad = 0) =>
// // // // // // // //       diamondIntersect(cx, cy, (dim.w + pad) / 2, (dim.h + pad) / 2, tx, ty),
// // // // // // // //     collide: (dim) => Math.max(dim.w, dim.h) / 2 + 8
// // // // // // // //   }
// // // // // // // // };

